      "importance": 4,
      "reason": "The previously recorded type assumption now extends to four explicitly typed marts columns.",
      "updates": "c2-2"
    },
    {
      "statement": "The klaviyo__events output may contain an additional copy of prev_occurred_on beyond the single column listed in its contract.",
      "about": "requirement",
      "target": "marts.klaviyo__events output schema",
      "evidence_of_dependence": "select s.*, ... prev_occurred_on,",
      "alternative": "The contract lists \"prev_occurred_on\" once, while sequenced already adds it to the columns included by \"s.*\".",
      "importance": 3,
      "reason": "Selecting the field twice can introduce an automatically renamed extra column into the materialized schema.",
      "updates": null
    },
    {
      "statement": "The first_event_on and last_event_on values retained from persons_enriched are always identical to the corresponding person_metrics values required as the primary activity dates.",
